<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>APRIL Coverage Levels</title>
  <style>
    body {
      font-family: Arial, sans-serif;
      color: #222;
      background: #fff;
      margin: 0;
      padding: 20px;
    }
    h2 {
      color: #004b7c;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      margin-top: 10px;
    }
    th, td {
      border: 1px solid #ccc;
      padding: 12px;
      text-align: left;
    }
    th {
      background-color: #e8f3f8;
      font-weight: bold;
    }
    caption {
      caption-side: bottom;
      text-align: left;
      font-style: italic;
      padding-top: 8px;
    }
  </style>
</head>
<body>

  <h2> Coverage Levels (Plans)</h2>

  <table>
    <thead>
      <tr>
        <th>Plan</th>
        <th>Annual Limit</th>
        <th>Hospitalisation Room</th>
      </tr>
    </thead>
    <tbody>
      <tr>
        <td>Emergency</td>
        <td>250,000 USD</td>
        <td>Two-bed (accident/emergency only)</td>
      </tr>
      <tr>
        <td>Basic</td>
        <td>500,000 USD</td>
        <td>Two-bed or standard private</td>
      </tr>
      <tr>
        <td>Essential</td>
        <td>1,000,000 USD</td>
        <td>Private room up to 75 USD/day</td>
      </tr>
      <tr>
        <td>Comfort</td>
        <td>1,500,000 USD</td>
        <td>Standard private room</td>
      </tr>
      <tr>
        <td>Premium</td>
        <td>Unlimited</td>
        <td>Standard private room</td>
      </tr>
    </tbody>
    <caption><em>Premium and Comfort may include higher ceilings or denials depending on zone</em></caption>
  </table>

</body>
</html>
